'use client';

import { useCallback, useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { FIELD_LABELS, RFQ_LABELS, fieldValue, type Field, type FollowUpTask, type Quote, type QuoteInput, type RFQDetail, type RFQStatus, type RFQSummary, type User } from '@/lib/contracts';

type View = 'inbox' | 'tasks';
type DetailTab = 'review' | 'quote' | 'activity';
type Sample = { id: string; title: string; description: string; files: string[] };
type Stats = { total: number; blockers: number; pendingApproval: number; overdue: number };
type IconName = 'inbox'|'arrow'|'plus'|'check'|'clock'|'file'|'search'|'close'|'upload'|'shield'|'chevron'|'alert'|'copy'|'refresh'|'logout'|'layers'|'link'|'download'|'menu';
const paths: Record<IconName, ReactNode> = {
  inbox: <><path d="M4 4h16v16H4z"/><path d="M4 13h5l2 3h2l2-3h5"/></>,
  arrow: <><path d="M4 12h15M13 6l6 6-6 6"/></>,
  plus: <path d="M12 5v14M5 12h14"/>,
  check: <path d="m5 12 4 4L19 6"/>,
  clock: <><circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2"/></>,
  file: <><path d="M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6"/></>,
  search: <><circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/></>,
  close: <path d="m6 6 12 12M18 6 6 18"/>,
  upload: <><path d="M12 15V3m-4 4 4-4 4 4M4 14v6h16v-6"/></>,
  shield: <><path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/></>,
  chevron: <path d="m9 5 7 7-7 7"/>,
  alert: <><path d="m12 3 10 18H2zM12 9v5"/><path d="M12 17h.01"/></>,
  copy: <><rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/></>,
  refresh: <><path d="M20 9a8 8 0 1 0 0 7M20 3v6h-6"/></>,
  logout: <><path d="M10 4H4v16h6M10 12h10m-4-4 4 4-4 4"/></>,
  layers: <><path d="m12 3 10 6-10 6L2 9zM2 14l10 6 10-6"/></>,
  link: <><path d="m10 14 4-4M8 16l-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0M14 8l2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0"/></>,
  download: <><path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/></>,
  menu: <path d="M4 6h16M4 12h16M4 18h16"/>,
};
function Icon({ name, size = 18 }: { name: IconName; size?: number }) { return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]}</svg>; }
function date(value: string | null, withTime = false) { if (!value) return '—'; const d = new Date(value); return Number.isNaN(d.getTime()) ? value : d.toLocaleString('zh-CN', withTime ? { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false } : { year: 'numeric', month: '2-digit', day: '2-digit' }); }
function money(value: string) { const n = Number(value); return Number.isFinite(n) ? n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : value; }
function dateInput(value: Date) { const offset = value.getTimezoneOffset() * 60_000; return new Date(value.getTime() - offset).toISOString().slice(0,16); }
async function api<T>(url: string, init?: RequestInit): Promise<T> { const response = await fetch(url, { ...init, headers: init?.body instanceof FormData ? init.headers : { 'Content-Type': 'application/json', ...init?.headers } }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.error || `请求失败（${response.status}）`); return body as T; }
function post<T>(url: string, body?: unknown) { return api<T>(url, { method: 'POST', ...(body !== undefined ? { body: JSON.stringify(body) } : {}) }); }
function Tag({ children, tone = 'muted' }: { children: ReactNode; tone?: 'muted'|'green'|'amber'|'red'|'blue' }) { return <span className={`tag tag-${tone}`}>{children}</span>; }
function Status({ status }: { status: RFQStatus }) { return <Tag tone={status === 'pending_approval' ? 'amber' : status === 'won' || status === 'quoted' ? 'green' : status === 'lost' ? 'muted' : 'blue'}>{RFQ_LABELS[status]}</Tag>; }
function QuoteStatus({ status }: { status: Quote['status'] }) { return <Tag tone={status === 'approved' ? 'green' : status === 'pending' ? 'amber' : status === 'returned' ? 'red' : 'muted'}>{{ draft: '内部草稿', pending: '待主管审批', returned: '已退回', approved: '已批准', superseded: '版本已失效' }[status]}</Tag>; }
function Empty({ title, children, action }: { title: string; children: ReactNode; action?: ReactNode }) { return <div className="empty-state"><span className="empty-icon"><Icon name="inbox" size={30}/></span><h3>{title}</h3><p>{children}</p>{action}</div>; }
function Modal({ title, subtitle, children, onClose, wide }: { title: string; subtitle?: string; children: ReactNode; onClose: () => void; wide?: boolean }) { const closeRef = useRef<HTMLButtonElement>(null); const panelRef = useRef<HTMLElement>(null); useEffect(() => { const previous = document.activeElement as HTMLElement | null; closeRef.current?.focus(); const key = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); if (e.key === 'Tab') { const nodes = panelRef.current?.querySelectorAll<HTMLElement>('button:not(:disabled), input, select, textarea, a[href]'); if (!nodes?.length) return; const first = nodes[0], last = nodes[nodes.length-1]; if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); } else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); } } }; document.addEventListener('keydown',key); const overflow = document.body.style.overflow; document.body.style.overflow = 'hidden'; return () => { document.removeEventListener('keydown',key); document.body.style.overflow = overflow; previous?.focus(); }; }, [onClose]); return <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><section ref={panelRef} className={`modal ${wide ? 'modal-wide' : ''}`} role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button ref={closeRef} className="icon-button" onClick={onClose} aria-label="关闭"><Icon name="close"/></button></div>{children}</section></div>; }

export default function App() {
  const [session, setSession] = useState<{ user: User|null; demoMode: boolean } | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [busy, setBusy] = useState('');
  const [view, setView] = useState<View>('inbox');
  const [rfqs, setRfqs] = useState<RFQSummary[]>([]);
  const [stats, setStats] = useState<Stats>({ total: 0, blockers: 0, pendingApproval: 0, overdue: 0 });
  const [users, setUsers] = useState<User[]>([]);
  const [tasks, setTasks] = useState<FollowUpTask[]>([]);
  const [selected, setSelected] = useState<string | null>(null);
  const selectedRef = useRef<string | null>(null);
  const [detail, setDetail] = useState<RFQDetail | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [tab, setTab] = useState<DetailTab>('review');
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('all');
  const [modal, setModal] = useState<'import'|'samples'|null>(null);
  const [samples, setSamples] = useState<Sample[]>([]);
  const [mobileNav, setMobileNav] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const closeModal = useCallback(() => setModal(null), []);
  const reloadLists = useCallback(async () => { const [inbox, team, followups] = await Promise.all([api<{rfqs:RFQSummary[];stats:Stats}>('/api/rfqs'), api<{users:User[]}>('/api/users'), api<{tasks:FollowUpTask[]}>('/api/tasks')]); setRfqs(inbox.rfqs); setStats(inbox.stats); setUsers(team.users); setTasks(followups.tasks); }, []);
  const refresh = useCallback(async () => { await reloadLists(); const id = selectedRef.current; if (id) { const data = await api<RFQDetail>(`/api/rfqs/${id}`); if (selectedRef.current === id) setDetail(data); } }, [reloadLists]);
  useEffect(() => { api<{user:User|null;demoMode:boolean}>('/api/session').then(result => { setSession(result); if (result.user) return reloadLists(); }).catch(e => setError(e.message)).finally(() => setLoading(false)); const handlePop = () => { const id = new URLSearchParams(window.location.search).get('rfq'); selectedRef.current = id; setSelected(id); }; handlePop(); window.addEventListener('popstate', handlePop); return () => window.removeEventListener('popstate',handlePop); }, [reloadLists]);
  useEffect(() => { if (!selected || !session?.user) { setDetail(null); return; } let alive = true; setDetailLoading(true); setDetail(null); api<RFQDetail>(`/api/rfqs/${selected}`).then(data => { if (alive) setDetail(data); }).catch(e => { if (alive) setError(e.message); }).finally(() => { if (alive) setDetailLoading(false); }); return () => { alive = false; }; }, [selected,session?.user?.id]);
  useEffect(() => { if (!notice) return; const timeout = setTimeout(() => setNotice(''),5500); return () => clearTimeout(timeout); },[notice]);
  async function act(key: string, fn: () => Promise<unknown>, success = '', reload = true) { setBusy(key); setError(''); try { await fn(); if (reload && session?.user) await refresh(); if (success) setNotice(success); return true; } catch (e) { setError(e instanceof Error ? e.message : '操作失败，请重试。'); return false; } finally { setBusy(''); } }
  function navigate(id: string | null, nextView: View = 'inbox') { selectedRef.current = id; setSelected(id); setView(nextView); setMobileNav(false); setError(''); if (id !== selected) setTab('review'); const url = new URL(window.location.href); if (id) url.searchParams.set('rfq',id); else url.searchParams.delete('rfq'); window.history.pushState({},'',url); }
  async function login(event: FormEvent) { event.preventDefault(); await act('login', async () => { const result = await post<{user:User}>('/api/login',{email,password}); setSession(old => ({user:result.user,demoMode:old?.demoMode ?? false})); setPassword(''); await reloadLists(); },'',false); }
  async function openSamples() { setModal('samples'); await act('samples',async () => { const result = await api<{samples:Sample[]}>('/api/samples'); setSamples(result.samples); },'',false); }
  const sales = session?.user?.role === 'sales';
  const filtered = rfqs.filter(r => (!search || `${r.customer} ${r.ownerName} ${r.id}`.toLowerCase().includes(search.toLowerCase())) && (filter === 'all' || filter === 'issues' ? filter !== 'issues' || r.blockers > 0 : r.status === filter));

  if (loading) return <main className="boot-screen"><Brand/><span className="spinner"/><p>正在打开工作台…</p></main>;
  if (!session?.user) return <main className="login-page"><section className="login-story"><Brand/><div><span className="eyebrow">MADE FOR MANUFACTURING EXPORTS</span><h1>把每一次询价，<br/>稳妥地变成下一步。</h1><p>原文、规格、报价和跟进，在同一个工作台。<br/>让信息有来处，让决策有依据。</p><div className="login-flow"><span>接收询价</span><Icon name="arrow"/><span>核实规格</span><Icon name="arrow"/><span>审批报价</span></div></div><small>QUOVOY / 人工决策，协作有序</small></section><section className="login-panel"><div className="login-card"><span className="eyebrow">YOUR EXPORT WORKSPACE</span><h2>欢迎回到 Quovoy</h2><p>登录，接着处理重要的事。</p>{error && <div className="feedback error" role="alert">{error}</div>}<form onSubmit={login}><label>工作邮箱<input type="email" autoComplete="username" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@company.com" required/></label><label>密码<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="输入登录密码" required/></label><button className="button primary full" disabled={!!busy}>{busy === 'login' ? '正在登录…' : '登录工作台'}<Icon name="arrow"/></button></form>{session?.demoMode && <div className="demo-login"><div><Tag tone="amber">本地演示模式</Tag><span>使用合成数据体验角色协作</span></div><div className="demo-role-buttons"><button onClick={()=>{setEmail('sales@quovoy.demo');setPassword('DemoSales!2026');}}>填入销售账号<small>整理 · 报价 · 跟进</small></button><button onClick={()=>{setEmail('manager@quovoy.demo');setPassword('DemoManager!2026');}}>填入主管账号<small>核实 · 审批 · 退回</small></button></div></div>}<p className="login-foot"><Icon name="shield" size={15}/>按组织隔离 · 按角色协作</p>{!session && <button className="text-button" onClick={()=>window.location.reload()}>重试连接</button>}</div></section></main>;

  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? 'mobile-open' : ''}`}><div className="sidebar-brand"><Brand/><button className="icon-button mobile-only" onClick={()=>setMobileNav(false)} aria-label="关闭导航"><Icon name="close"/></button></div><div className="workspace-label"><span className="workspace-dot"/>制造业 · 出口工作台</div><p className="nav-caption">日常工作</p><nav><button className={view==='inbox'?'active':''} onClick={()=>navigate(null,'inbox')}><Icon name="inbox"/><span>询价收件箱</span><span className="nav-count">{stats.total}</span></button><button className={view==='tasks'?'active':''} onClick={()=>navigate(null,'tasks')}><Icon name="clock"/><span>跟进看板</span>{stats.overdue>0&&<span className="nav-alert">{stats.overdue}</span>}</button></nav><div className="sidebar-guide"><span className="guide-icon"><Icon name="layers"/></span><h3>每一步，都有依据</h3><p>回到原文核实规格，<br/>在发送前完成审批。</p><div className="guide-steps"><i/><i/><i/><i/></div></div><div className="sidebar-bottom">{session.demoMode&&<button className="sample-nav" onClick={openSamples}><Icon name="layers"/><span>合成样本库</span><Icon name="chevron" size={14}/></button>}<div className="session-user"><span className="avatar">{session.user.name.slice(0,1)}</span><div><strong>{session.user.name}</strong><small>{sales?'销售 · 编辑与报价':'主管 · 审批与退回'}</small></div><button className="icon-button" title="退出登录" aria-label="退出登录" onClick={()=>act('logout',async()=>{await post('/api/logout');setSession(old=>({user:null,demoMode:old?.demoMode??false}));setDetail(null);setRfqs([]);setTasks([]);setUsers([]);},'',false)}><Icon name="logout" size={17}/></button></div></div></aside>
    <main className="main-area"><header className="topbar"><div className="topbar-crumb"><button className="icon-button mobile-only" onClick={()=>setMobileNav(true)} aria-label="打开导航"><Icon name="menu"/></button><span>工作台</span><span className="crumb-slash">/</span><strong>{view==='tasks'?'跟进看板':selected?'询价详情':'询价收件箱'}</strong></div><div className="topbar-right">{session.demoMode&&<span className="demo-pill"><span/>演示模式 · 合成样本不代表真实效果</span>}<button className="icon-button" aria-label="刷新数据" title="刷新数据" disabled={!!busy} onClick={()=>act('refresh',async()=>refresh(),'已刷新',false)}><Icon name="refresh"/></button><span className="topbar-avatar">{session.user.name.slice(0,1)}</span></div></header>
    <div className="page-content">{error && <div className="feedback error" role="alert"><Icon name="alert"/><span>{error}</span><button className="icon-button" onClick={()=>setError('')} aria-label="关闭错误提示"><Icon name="close" size={16}/></button></div>}{notice&&<div className="feedback success" role="status"><Icon name="check"/><span>{notice}</span></div>}
    {view==='tasks' ? <><div className="page-heading"><div><span className="eyebrow">FOLLOW THROUGH</span><h1>把下一步，放在日程里。</h1><p>关注到期任务，让每一次沟通都有回音。</p></div></div><TaskBoard tasks={tasks} users={users} rfqs={rfqs} user={session.user} busy={busy} act={act} onOpen={id=>navigate(id)}/></> : selected ? detailLoading ? <div className="loading-card"><span className="spinner"/>正在读取询价与原始材料…</div> : detail ? <><button className="back-button" onClick={()=>navigate(null)}><span>←</span> 返回收件箱</button><div className="detail-heading"><div><div className="title-tags"><span className="eyebrow">RFQ / {detail.id.slice(-8).toUpperCase()}</span>{detail.synthetic&&<Tag tone="amber">合成演示</Tag>}<Status status={detail.status}/></div><h1>{detail.customer || '待确认客户'}</h1><p>{date(detail.createdAt,true)} 导入<span className="dot-sep">·</span>{detail.itemCount} 条产品明细<span className="dot-sep">·</span>修订 {detail.revision}</p></div><div className="detail-controls"><label>负责人<select aria-label="询价负责人" value={detail.ownerId} disabled={!sales||!!busy} onChange={e=>act('owner',()=>api(`/api/rfqs/${detail.id}`,{method:'PATCH',body:JSON.stringify({ownerId:e.target.value})}),'负责人已更新')} >{users.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select></label><label>询价状态<select aria-label="询价状态" value={detail.status} disabled={!sales||!!busy} onChange={e=>act('status',()=>api(`/api/rfqs/${detail.id}`,{method:'PATCH',body:JSON.stringify({status:e.target.value})}),'询价状态已更新')}>{Object.entries(RFQ_LABELS).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label></div></div><div className="detail-tabs"><button className={tab==='review'?'active':''} onClick={()=>setTab('review')}><Icon name="file"/>原文与审核{detail.blockers>0&&<span className="small-count">{detail.blockers}</span>}</button><button className={tab==='quote'?'active':''} onClick={()=>setTab('quote')}><Icon name="layers"/>报价与审批{detail.quotes.length>0&&<span className="tab-count">{detail.quotes.length}</span>}</button><button className={tab==='activity'?'active':''} onClick={()=>setTab('activity')}><Icon name="clock"/>跟进与记录</button></div>{tab==='review'&&<ReviewWorkspace key={detail.id} detail={detail} sales={sales} busy={busy} act={act} onQuote={()=>setTab('quote')}/>}{tab==='quote'&&<QuoteWorkspace key={detail.id} detail={detail} user={session.user} busy={busy} act={act} onReview={()=>setTab('review')}/>} {tab==='activity'&&<><TaskBoard tasks={detail.tasks} users={users} rfqs={[detail]} user={session.user} busy={busy} act={act} onOpen={id=>navigate(id)} fixedRFQ={detail.id}/><section className="panel audit-panel"><div className="panel-heading"><div><h2>操作记录</h2><p>字段、审批、导出与任务操作留痕。</p></div><Tag>{detail.audit.length} 条记录</Tag></div><div className="audit-list">{detail.audit.length ? detail.audit.map(event=><div className="audit-event" key={event.id}><span className="timeline-dot"/><div><strong>{auditLabel(event.action)}</strong><p>{auditDetail(event.action,event.detail)}</p><small>{event.actorName} · {date(event.createdAt,true)}</small></div></div>):<p className="subtle">暂无操作记录。</p>}</div></section></>}</> : <Empty title="未能打开这份询价" action={<button className="button" onClick={()=>act('retry-detail',async()=>setDetail(await api<RFQDetail>(`/api/rfqs/${selected}`)),'',false)}>重新读取</button>}>检查网络或从收件箱重新打开。</Empty> : <><div className="page-heading"><div><span className="eyebrow">LESS ADMIN. MORE PROGRESS.</span><h1>询价有序，生意向前。</h1><p>从收到第一封邮件，到发出一份有依据的报价。</p></div><div className="heading-actions">{session.demoMode&&<button className="button" onClick={openSamples}><Icon name="layers"/>体验样本</button>}<button className="button primary" onClick={()=>setModal('import')} disabled={!sales}><Icon name="plus"/>导入询价</button></div></div><section className="stats-grid" aria-label="工作概览"><Stat label="全部询价" value={stats.total} note="已保存到工作台" icon="inbox"/><Stat label="待核实询价" value={stats.blockers} note="含有审批阻塞的询价数" icon="alert" tone="amber"/><Stat label="等待审批" value={stats.pendingApproval} note="等待主管核实报价" icon="shield"/><Stat label="逾期跟进" value={stats.overdue} note="留意需要回复的客户" icon="clock" tone={stats.overdue?'red':'green'}/></section><section className="panel inbox-panel"><div className="inbox-toolbar"><div className="filter-tabs"><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>全部询价 <span>{rfqs.length}</span></button><button className={filter==='issues'?'active':''} onClick={()=>setFilter('issues')}>待核实</button><button className={filter==='pending_approval'?'active':''} onClick={()=>setFilter('pending_approval')}>待审批</button><button className={filter==='quoted'?'active':''} onClick={()=>setFilter('quoted')}>已报价</button></div><label className="search-box"><Icon name="search"/><input aria-label="搜索客户或负责人" value={search} onChange={e=>setSearch(e.target.value)} placeholder="搜索客户、负责人…"/></label></div>{filtered.length ? <div className="table-scroll"><table className="inbox-table"><thead><tr><th>客户 / 询价</th><th>处理状态</th><th>产品明细</th><th>核实情况</th><th>负责人</th><th>导入时间</th><th aria-label="打开"/></tr></thead><tbody>{filtered.map(r=><tr key={r.id}><td><button className="customer-link" onClick={()=>navigate(r.id)}><span className="customer-avatar">{r.customer?.slice(0,1)||'?'}</span><span><strong>{r.customer||'待确认客户'}</strong><small>{r.synthetic?'合成演示 · ':''}RFQ-{r.id.slice(-6).toUpperCase()}</small></span></button></td><td><Status status={r.status}/></td><td><span className="item-quantity">{r.itemCount}</span><span className="subtle"> 条</span></td><td>{r.blockers>0?<span className="issue-summary"><i/>{r.blockers} 项阻塞</span>:r.issues>0?<span className="subtle">{r.issues} 项提示</span>:<span className="clear-summary"><Icon name="check" size={14}/>暂无问题</span>}</td><td><span className="owner-cell"><i>{r.ownerName.slice(0,1)}</i>{r.ownerName}</span></td><td className="date-cell">{date(r.createdAt)}</td><td><button className="icon-button" aria-label={`打开 ${r.customer}`} onClick={()=>navigate(r.id)}><Icon name="chevron" size={17}/></button></td></tr>)}</tbody></table></div>:<Empty title={rfqs.length?'没有符合条件的询价':'下一份报价，从一封询价开始。'} action={rfqs.length?<button className="button" onClick={()=>{setSearch('');setFilter('all');}}>清除筛选</button>:sales?<button className="button primary" onClick={()=>setModal('import')}><Icon name="plus"/>导入第一份询价</button>:undefined}>{rfqs.length?'试试其他客户名称，或查看全部询价。':'粘贴邮件或上传附件，保留原文，逐项核实。'}</Empty>}<div className="table-footer"><span>共 {filtered.length} 份询价</span><span><Icon name="shield" size={13}/>人工审批后导出 · 发送由你确认</span></div></section><div className="workflow-strip"><div><span className="eyebrow">A CLEAR PATH FOR EVERY RFQ</span><h3>从原文到跟进，重要信息不掉队。</h3></div><div className="workflow-nodes">{['导入原文','核实规格','成本报价','人工审批','发送与跟进'].map((s,i)=><span key={s}><i>{String(i+1).padStart(2,'0')}</i>{s}{i<4&&<Icon name="chevron" size={13}/>}</span>)}</div></div></>}
    </div><footer className="app-footer"><span>QUOVOY <span className="dot-sep">·</span> 工作有序，判断由你。</span><span>外发内容须经人工核实</span></footer></main>
    {modal==='import'&&<ImportModal onClose={closeModal} busy={busy} act={act} onImported={id=>{setModal(null);navigate(id);}}/>}
    {modal==='samples'&&<Modal title="合成样本库" subtitle="用于检查功能与异常处理，不代表真实模型准确率或商业效果。" onClose={closeModal} wide>{busy==='samples'?<div className="loading-card"><span className="spinner"/>读取样本…</div>:<div className="sample-grid">{samples.map((sample,i)=><article className="sample-card" key={sample.id}><span className="sample-number">{String(i+1).padStart(2,'0')}</span><h3>{sample.title}</h3><p>{sample.description}</p><div className="sample-files">{sample.files.map(f=><span key={f}><Icon name="file" size={12}/>{f}</span>)}</div><button className="button small" disabled={!!busy||!sales} onClick={()=>act(`sample-${sample.id}`,async()=>{const result=await post<{rfqId:string;duplicate:boolean}>(`/api/samples/${sample.id}/import`);setModal(null);navigate(result.rfqId);setNotice(result.duplicate?'已识别重复样本，打开已有询价。':'合成样本已导入。');},'',true)}>{busy===`sample-${sample.id}`?'正在导入…':'导入样本'}<Icon name="arrow" size={14}/></button></article>)}</div>}{!sales&&<div className="inline-note">主管可查看与审批；切换为销售账号后导入样本。</div>}</Modal>}
  </div>;
}

function Brand() { return <div className="brand"><span className="brand-mark">q<span/></span><span>quovoy<span className="brand-period">.</span></span></div>; }
function Stat({label,value,note,icon,tone='green'}:{label:string;value:number;note:string;icon:IconName;tone?:string}) { return <div className="stat-card"><div><span>{label}</span><span className={`stat-icon ${tone}`}><Icon name={icon}/></span></div><strong>{value}<small>项</small></strong><p>{note}</p></div>; }
type Act = (key:string,fn:()=>Promise<unknown>,success?:string,reload?:boolean)=>Promise<boolean>;
function ImportModal({onClose,busy,act,onImported}:{onClose:()=>void;busy:string;act:Act;onImported:(id:string)=>void}) {
 const [text,setText]=useState(''); const [files,setFiles]=useState<File[]>([]); const [synthetic,setSynthetic]=useState(false);
 async function submit(e:FormEvent){e.preventDefault(); const form=new FormData();form.set('text',text);form.set('synthetic',String(synthetic));files.forEach(f=>form.append('files',f));await act('import',async()=>{const result=await api<{rfqId:string;duplicate:boolean}>('/api/rfqs',{method:'POST',body:form});onImported(result.rfqId);},'导入完成；如内容重复，将打开已存在的询价。');}
 return <Modal title="导入一份询价" subtitle="同一询价的邮件和附件可以一起导入，来源会分别保留。" onClose={onClose}><form className="import-form" onSubmit={submit}><label>邮件正文<textarea rows={8} value={text} onChange={e=>setText(e.target.value)} placeholder={'粘贴客户邮件，保留型号、数量、单位与原始规格。\n\nDear team,\nPlease quote the following components…'}/></label><label className="upload-zone"><Icon name="upload" size={25}/><strong>选择附件，可同时上传多个文件</strong><span>支持 .eml、文本型 PDF、.xlsx、.txt</span><small>扫描件、图片和工程图纸将明确标记为需人工处理</small><input type="file" multiple aria-label="选择询价附件" onChange={e=>setFiles(Array.from(e.target.files||[]))}/></label>{files.length>0&&<ul className="file-list">{files.map((f,i)=><li key={`${f.name}-${i}`}><Icon name="file"/><span>{f.name}<small>{(f.size/1024).toFixed(1)} KB</small></span><button type="button" className="icon-button" aria-label={`移除 ${f.name}`} onClick={()=>setFiles(old=>old.filter((_,j)=>j!==i))}><Icon name="close" size={15}/></button></li>)}</ul>}<label className="check-label"><input type="checkbox" checked={synthetic} onChange={e=>setSynthetic(e.target.checked)}/>这是合成演示数据</label><div className="inline-note"><Icon name="shield" size={15}/>原文用于提取与核实；附件内容不会触发外发或系统操作。</div><div className="modal-actions"><button type="button" className="button" onClick={onClose}>取消</button><button className="button primary" disabled={!!busy||(!text.trim()&&!files.length)}>{busy==='import'?'正在解析并保存…':'保存并解析'}<Icon name="arrow" size={16}/></button></div></form></Modal>;
}

function ReviewWorkspace({detail,sales,busy,act,onQuote}:{detail:RFQDetail;sales:boolean;busy:string;act:Act;onQuote:()=>void}) {
 const [documentId,setDocumentId]=useState(detail.documents[0]?.id||''); const [locator,setLocator]=useState(''); const [values,setValues]=useState<Record<string,string>>({}); const [timeMinutes,setTimeMinutes]=useState(''); const [copyMessage,setCopyMessage]=useState(''); const [draftTab,setDraftTab]=useState<'clarification'|'supplier'>('clarification');
 const allFields=[...detail.fields,...detail.items.flatMap(item=>item.fields)];
 const reviewed=allFields.filter(f=>f.confirmed).length;
 const doc=detail.documents.find(d=>d.id===documentId)||detail.documents[0];
 useEffect(()=>{if(!locator)return;const el=document.getElementById(`source-${encodeURIComponent(locator)}`);el?.scrollIntoView({behavior:'smooth',block:'nearest'});},[locator,documentId]);
 function showSource(field:Field){if(field.sourceDocumentId){setDocumentId(field.sourceDocumentId);setLocator(field.sourceLocator||'');}}
 async function save(field:Field,confirmed:boolean){const value=values[field.id]??fieldValue(field);const ok=await act(`field-${field.id}`,()=>api(`/api/rfqs/${detail.id}/fields/${field.id}`,{method:'PATCH',body:JSON.stringify({value,confirmed})}),confirmed?'字段已确认并保存。':'修改已保存，字段待核实。');if(ok)setValues(old=>{const next={...old};delete next[field.id];return next;});}
 async function confirmAll(){const pending=allFields.filter(f=>!f.confirmed||values[f.id]!==undefined);const ok=await act('confirm-all',async()=>{for(const f of pending){await api(`/api/rfqs/${detail.id}/fields/${f.id}`,{method:'PATCH',body:JSON.stringify({value:values[f.id]??fieldValue(f),confirmed:true})});}},'所有字段已逐项保存并确认；缺失项仍需补充。');if(ok)setValues({});}
 async function copy(text:string){try{await navigator.clipboard.writeText(text);setCopyMessage('已复制，可粘贴至邮件客户端。');}catch{setCopyMessage('复制不可用，请选中下方草稿手动复制。');}}
 function fieldCard(field:Field){const modified=values[field.id]!==undefined&&values[field.id]!==fieldValue(field);return <div className={`field-card ${field.confirmed&&!modified?'is-confirmed':''}`} key={field.id}><div className="field-label"><label htmlFor={`field-${field.id}`}>{FIELD_LABELS[field.key]||field.key}</label><span>{modified?<Tag tone="amber">未保存</Tag>:field.confirmed?<span className="field-confirmed"><Icon name="check" size={12}/>已确认</span>:<span className="field-unconfirmed">待核实</span>}</span></div><div className="field-input-row"><input id={`field-${field.id}`} value={values[field.id]??fieldValue(field)} disabled={!sales||!!busy} placeholder="未提供 · 请人工核实" onChange={e=>setValues(old=>({...old,[field.id]:e.target.value}))}/>{sales&&<button className={`confirm-button ${field.confirmed&&!modified?'confirmed':''}`} disabled={!!busy||(field.confirmed&&!modified)} title="保存并确认该字段" aria-label={`确认${FIELD_LABELS[field.key]||field.key}`} onClick={()=>save(field,true)}><Icon name="check" size={16}/></button>}</div><div className="field-provenance"><span>{{rule:'规则提取',model:'模型提取',manual:'人工输入'}[field.method]}</span>{field.sourceDocumentId?<button onClick={()=>showSource(field)} title={field.excerpt||'查看原文'}><Icon name="link" size={12}/>{field.sourceLocator||'查看来源'}</button>:<span>无可定位来源</span>}{modified&&<button className="save-unconfirmed" disabled={!!busy} onClick={()=>save(field,false)}>保存修改</button>}</div>{field.verificationReason&&!field.confirmed&&<p className="verification-note">{field.verificationReason}</p>}{field.excerpt&&<details className="field-excerpt"><summary>原始值与摘录</summary><p>原始值：{field.rawValue||'未提供'}</p><blockquote>{field.excerpt}</blockquote>{field.editedAt&&<small>修改人 {field.editedBy||'用户'} · {date(field.editedAt,true)}</small>}</details>}</div>;}
 return <><div className="review-summary"><div><span className="review-ring"><Icon name="shield" size={22}/></span><div><strong>{detail.blockers?`${detail.blockers} 项阻塞需要核实`:'核对原文，确认关键规格'}</strong><p>{reviewed} / {allFields.length} 个字段已确认 · 允许保存不完整草稿</p></div></div><div className="review-actions"><button className="button small" disabled={!sales||!!busy||!allFields.length} onClick={confirmAll}>{busy==='confirm-all'?'正在逐项保存…':'我已核实，确认全部'}</button><button className="button primary small" onClick={onQuote}>进入报价<Icon name="arrow" size={15}/></button></div></div><div className="review-grid"><section className="panel source-panel"><div className="panel-heading"><div><span className="eyebrow">SOURCE OF TRUTH</span><h2>原始材料</h2></div><span className="document-count">{detail.documents.length} 份</span></div><div className="document-tabs">{detail.documents.map(d=><button className={doc?.id===d.id?'active':''} key={d.id} onClick={()=>{setDocumentId(d.id);setLocator('');}} title={d.filename}><Icon name="file" size={14}/>{d.filename}{d.status!=='parsed'&&<span className="file-warning-dot"/>}</button>)}</div>{doc?<><div className="source-meta"><span><Tag tone={doc.status==='parsed'?'green':'amber'}>{doc.status==='parsed'?'已读取原文':doc.status==='failed'?'解析失败':'未解析 · 人工补录'}</Tag></span><a href={`/api/documents/${doc.id}`} target="_blank" rel="noreferrer"><Icon name="download" size={13}/>原文件</a></div>{doc.warnings.length>0&&<div className="document-warnings">{doc.warnings.map((warning,i)=><p key={i}><Icon name="alert" size={13}/>{warning}</p>)}</div>}<div className="source-body">{doc.segments.length?doc.segments.map((segment,i)=><div className={`source-segment ${locator&&segment.locator===locator?'highlighted':''}`} id={`source-${encodeURIComponent(segment.locator)}`} key={`${segment.locator}-${i}`}><span className="source-location">{segment.locator}</span><pre>{segment.text}</pre></div>):doc.text?<pre className="source-full-text">{doc.text}</pre>:<Empty title="这份材料需要人工查看">下载原文件后补录右侧字段。工程图纸尺寸、公差与工艺须由人确认。</Empty>}</div></>:<Empty title="没有原始材料">这份询价尚未保存可展示的原文。</Empty>}<div className="source-footer"><Icon name="link" size={13}/>点击右侧字段来源，即可定位原文。</div></section><section className="panel fields-panel"><div className="panel-heading"><div><span className="eyebrow">HUMAN REVIEW</span><h2>结构化询价</h2></div><span className="subtle">{sales?'编辑后点击 ✓ 保存确认':'主管查看模式'}</span></div><div className="field-section"><h3><span>01</span> 客户与商业条件</h3><div className="fields-grid">{detail.fields.map(fieldCard)}</div></div>{detail.items.map((item,i)=><div className="field-section product-section" key={item.id}><h3><span>{String(i+2).padStart(2,'0')}</span> 产品 {i+1}<small>{fieldValue(item.fields.find(f=>f.key==='model'))||'型号待确认'}</small></h3><div className="fields-grid">{item.fields.map(fieldCard)}</div></div>)}{sales&&<button className="add-product" disabled={!!busy} onClick={()=>act('add-item',()=>post(`/api/rfqs/${detail.id}/items`),'已增加空白产品行，请核实后填写。')}><Icon name="plus" size={16}/>新增产品行</button>}</section></div>
 <div className="below-review-grid"><section className="panel issues-panel"><div className="panel-heading"><div><h2>缺失与冲突</h2><p>阻塞项影响审批，提示项可保留在草稿中。</p></div><Tag tone={detail.blockers?'amber':'green'}>{detail.issuesList.length} 项</Tag></div><div className="issues-list">{detail.issuesList.length?detail.issuesList.map(issue=><article className={`issue-card ${issue.severity}`} key={issue.id}><Icon name={issue.severity==='blocker'?'alert':'file'} size={17}/><div><div className="issue-heading"><strong>{issue.message}</strong><Tag tone={issue.severity==='blocker'?'red':'amber'}>{issue.severity==='blocker'?'阻止审批':'提示'}</Tag></div>{issue.sourceLocations.length>0&&<p>{issue.sourceLocations.join(' · ')}</p>}{issue.fieldIds.length>0&&<div className="issue-field-links">{issue.fieldIds.map(id=>{const f=allFields.find(v=>v.id===id);return f?<button key={id} onClick={()=>{showSource(f);document.getElementById(`field-${f.id}`)?.focus();}}>{FIELD_LABELS[f.key]||f.key}<Icon name="arrow" size={12}/></button>:null;})}</div>}</div></article>):<div className="all-clear"><Icon name="check"/>当前未发现规则问题。请继续核实规格与商业条款。</div>}</div>{detail.jobs.some(job=>job.status==='failed')&&<div className="retry-job"><p>解析作业存在失败记录，可重试或直接人工补录。</p><button className="button small" disabled={!sales||!!busy} onClick={()=>act('retry-parse',()=>post(`/api/rfqs/${detail.id}/retry`),'已执行重试，请检查来源与字段。')}><Icon name="refresh" size={14}/>重试解析</button></div>}</section><section className="panel drafts-panel"><div className="panel-heading"><div><h2>沟通草稿</h2><p>只使用已知信息，由你核实后复制发送。</p></div><button className="button small" onClick={()=>copy(draftTab==='clarification'?detail.clarificationDraft:detail.supplierDraft)}><Icon name="copy" size={14}/>复制</button></div><div className="mini-tabs"><button className={draftTab==='clarification'?'active':''} onClick={()=>setDraftTab('clarification')}>客户澄清</button><button className={draftTab==='supplier'?'active':''} onClick={()=>setDraftTab('supplier')}>供应商询价</button></div><textarea className="draft-text" readOnly aria-label={draftTab==='clarification'?'英文客户澄清草稿':'英文供应商询价草稿'} value={draftTab==='clarification'?detail.clarificationDraft:detail.supplierDraft}/>{copyMessage&&<p className="copy-feedback" role="status">{copyMessage}</p>}</section></div><section className="review-time"><div><Icon name="clock"/><div><strong>实际人工审核耗时</strong><p>累计 {(detail.reviewSeconds/60).toFixed(1)} 分钟 · 仅记录实际操作，不含等待客户或供应商的时间。</p></div></div><form onSubmit={e=>{e.preventDefault();const seconds=Math.round(Number(timeMinutes)*60);if(Number.isFinite(seconds)&&seconds>0)void act('time',()=>post(`/api/rfqs/${detail.id}/review-time`,{seconds}),'本次人工审核耗时已记录。').then(ok=>{if(ok)setTimeMinutes('');});}}><label><input aria-label="本次审核分钟数" type="number" min="0.1" max="480" step="0.1" required placeholder="本次" value={timeMinutes} onChange={e=>setTimeMinutes(e.target.value)}/>分钟</label><button className="button small" disabled={!!busy}>记录耗时</button></form></section></>;
}

function QuoteWorkspace({detail,user,busy,act,onReview}:{detail:RFQDetail;user:User;busy:string;act:Act;onReview:()=>void}) {
 const latest=[...detail.quotes].sort((a,b)=>b.version-a.version)[0];
 const [selectedQuoteId,setSelectedQuoteId]=useState(latest?.id||'');
 const selectedQuote=detail.quotes.find(q=>q.id===selectedQuoteId)||latest;
 const [input,setInput]=useState<QuoteInput>(()=>detail.quoteDraft||latest?.input||{unitCosts:{},freight:'',otherCosts:'',markupPercent:'',exchangeRate:'',costCurrency:'',quoteCurrency:fieldValue(detail.fields.find(f=>f.key==='currency')),validUntil:'',deliveryTerms:fieldValue(detail.fields.find(f=>f.key==='targetDelivery')),paymentTerms:fieldValue(detail.fields.find(f=>f.key==='paymentTerms')),incoterms:fieldValue(detail.fields.find(f=>f.key==='incoterms')),emailSubject:'',emailBody:''});
 const [reason,setReason]=useState(''); const [edited,setEdited]=useState(!!detail.quoteDraft); const [copyNotice,setCopyNotice]=useState(''); const sales=user.role==='sales';
 function change(key:keyof QuoteInput,value:string){setInput(old=>({...old,[key]:value}));setEdited(true);}
 function loadQuote(q:Quote){setSelectedQuoteId(q.id);setInput({...q.input,emailSubject:q.emailSubject,emailBody:q.emailBody});setEdited(false);}
 async function save(e:FormEvent){e.preventDefault();await act('quote-save',async()=>{const body={...input,...(!input.emailSubject?{emailSubject:undefined}:{}),...(!input.emailBody?{emailBody:undefined}:{})};const quote=await post<Quote>(`/api/rfqs/${detail.id}/quotes`,body);setSelectedQuoteId(quote.id);setInput({...quote.input,emailSubject:quote.emailSubject,emailBody:quote.emailBody});setEdited(false);},'已计算并保存新的报价版本。');}
 const actualInput=selectedQuote?.input;
 return <div className="quote-layout"><section className="panel quote-builder"><div className="panel-heading"><div><span className="eyebrow">COST → PRICE</span><h2>成本与报价规则</h2><p>{sales?'人工填入成本，每次保存生成独立版本。':'主管可查看确定版本，核实后审批。'}</p></div>{edited&&<Tag tone="amber">有未保存修改</Tag>}</div><form onSubmit={save}><div className="quote-form-content"><div className="section-label">产品成本</div><div className="cost-list">{detail.items.map((item,i)=>{const get=(key:string)=>fieldValue(item.fields.find(f=>f.key===key));return <label className="cost-item" key={item.id}><div><span className="cost-index">{String(i+1).padStart(2,'0')}</span><span><strong>{get('productName')||'未命名产品'}</strong><small>{get('model')||'型号待确认'} · {get('quantity')||'?'} {get('unit')||'单位待确认'}</small></span></div><span className="unit-cost"><span>单位成本</span><input aria-label={`产品 ${i+1} 单位成本`} inputMode="decimal" value={input.unitCosts[item.id]||''} placeholder="必须明确填写" disabled={!sales||!!busy} onChange={e=>{setInput(old=>({...old,unitCosts:{...old.unitCosts,[item.id]:e.target.value}}));setEdited(true);}}/></span></label>;})}</div><div className="quote-fields two-col"><label>运费<input inputMode="decimal" value={input.freight} onChange={e=>change('freight',e.target.value)} disabled={!sales||!!busy} placeholder="无运费请明确填 0"/></label><label>其他费用<input inputMode="decimal" value={input.otherCosts} onChange={e=>change('otherCosts',e.target.value)} disabled={!sales||!!busy} placeholder="无其他费用请明确填 0"/></label></div><div className="section-label">计算规则</div><div className="quote-fields two-col"><label>成本币种<input value={input.costCurrency} onChange={e=>change('costCurrency',e.target.value.toUpperCase())} disabled={!sales||!!busy} placeholder="例如 CNY" maxLength={3}/></label><label>报价币种<input value={input.quoteCurrency} onChange={e=>change('quoteCurrency',e.target.value.toUpperCase())} disabled={!sales||!!busy} placeholder="例如 USD" maxLength={3}/></label><label>加价率 %<input inputMode="decimal" value={input.markupPercent} onChange={e=>change('markupPercent',e.target.value)} disabled={!sales||!!busy} placeholder="例如 25"/></label><label>人工汇率<input inputMode="decimal" value={input.exchangeRate} onChange={e=>change('exchangeRate',e.target.value)} disabled={!sales||!!busy} placeholder="例如 7.2"/></label></div><div className="formula-note"><strong>1 {input.quoteCurrency||'报价币种'} = {input.exchangeRate||'X'} {input.costCurrency||'成本币种'}</strong><p>总价 =（产品成本 + 运费 + 其他费用）×（1 + 加价率）÷ 汇率</p><p>加价率 25% 对应毛利率 20%。不自动计入税费；汇率由人工录入。</p></div><div className="section-label">商业条款</div><div className="quote-fields two-col"><label>报价有效期<input type="date" value={input.validUntil} onChange={e=>change('validUntil',e.target.value)} disabled={!sales||!!busy}/></label><label>Incoterms<input value={input.incoterms} onChange={e=>change('incoterms',e.target.value)} disabled={!sales||!!busy} placeholder="未确认可留空"/></label><label>交期<input value={input.deliveryTerms} onChange={e=>change('deliveryTerms',e.target.value)} disabled={!sales||!!busy} placeholder="未确认可留空"/></label><label>付款条件<input value={input.paymentTerms} onChange={e=>change('paymentTerms',e.target.value)} disabled={!sales||!!busy} placeholder="未确认可留空"/></label></div><details className="email-editor" open={!!input.emailBody}><summary>英文报价邮件 · 可人工编辑</summary><p>首次计算后生成邮件。修改邮件并保存新版本后，需重新审批。</p><label>Subject<input value={input.emailSubject||''} onChange={e=>change('emailSubject',e.target.value)} disabled={!sales||!!busy} placeholder="首次计算时生成"/></label><label>Message<textarea rows={10} value={input.emailBody||''} onChange={e=>change('emailBody',e.target.value)} disabled={!sales||!!busy} placeholder="首次计算时根据报价内容生成英文草稿"/></label></details></div>{sales&&<div className="quote-save-bar"><button type="button" className="button full" disabled={!!busy} onClick={()=>act('quote-draft',()=>post(`/api/rfqs/${detail.id}/quote-draft`,input),'未完成报价已暂存，刷新后可继续；暂存不产生可审批金额。')}>{busy==='quote-draft'?'正在暂存…':'暂存未完成报价'}</button><small>成本不完整时也可暂存；保存修改会使旧审批失效。</small><button className="button primary full" disabled={!!busy||detail.items.length===0}>{busy==='quote-save'?'正在计算并保存…':'计算并保存新版本'}<Icon name="arrow" size={16}/></button><small>价格、规格或邮件变更，均需重新审批。</small></div>}</form></section><div className="quote-right"><section className="panel quote-preview"><div className="panel-heading"><div><span className="eyebrow">QUOTE PREVIEW</span><h2>报价预览</h2></div>{detail.quotes.length>0&&<select aria-label="选择报价版本" value={selectedQuote?.id||''} onChange={e=>{const q=detail.quotes.find(q=>q.id===e.target.value);if(q)loadQuote(q);}}>{[...detail.quotes].sort((a,b)=>b.version-a.version).map(q=><option key={q.id} value={q.id}>V{q.version} · {{draft:'草稿',pending:'待审批',returned:'退回',approved:'已批准',superseded:'已失效'}[q.status]}</option>)}</select>}</div>{selectedQuote&&actualInput?<><div className="quote-document"><div className="quote-doc-top"><Brand/><QuoteStatus status={selectedQuote.status}/></div><div className="quote-doc-title"><div><span>QUOTATION</span><h3>{actualInput.customerName||detail.customer}</h3><p>QUOTE V{selectedQuote.version} · RFQ REV {selectedQuote.rfqRevision}</p></div><span className="quote-currency">{actualInput.quoteCurrency}</span></div><div className="table-scroll"><table className="quote-table"><thead><tr><th>产品 / 规格</th><th>数量</th><th>金额</th></tr></thead><tbody>{selectedQuote.totals.lines.map(line=><tr key={line.itemId}><td><strong>{line.name||'—'}</strong><span>{line.model}</span><small>{line.specifications}</small></td><td>{line.quantity} {line.unit}</td><td>{money(line.saleTotal)}</td></tr>)}<tr className="fee-row"><td>Freight / 运费</td><td>—</td><td>{money(selectedQuote.totals.freightSale)}</td></tr><tr className="fee-row"><td>Other / 其他费用</td><td>—</td><td>{money(selectedQuote.totals.otherSale)}</td></tr>{Number(selectedQuote.totals.roundingAdjustment)!==0&&<tr className="fee-row"><td>Rounding / 舍入调整</td><td>—</td><td>{money(selectedQuote.totals.roundingAdjustment)}</td></tr>}</tbody></table></div><div className="quote-total"><span>报价总额<small>{actualInput.quoteCurrency}</small></span><strong>{money(selectedQuote.totals.total)}</strong></div><div className="internal-metrics"><span>成本合计<strong>{actualInput.costCurrency} {money(selectedQuote.totals.costTotal)}</strong></span><span>加价率<strong>{actualInput.markupPercent}%</strong></span><span>毛利率<strong>{selectedQuote.totals.grossMarginPercent}{Number.isFinite(Number(selectedQuote.totals.grossMarginPercent))?'%':''}</strong></span></div><dl className="quote-terms"><div><dt>Valid until</dt><dd>{actualInput.validUntil||'To be confirmed'}</dd></div><div><dt>Delivery</dt><dd>{actualInput.deliveryTerms||'To be confirmed'}</dd></div><div><dt>Payment</dt><dd>{actualInput.paymentTerms||'To be confirmed'}</dd></div><div><dt>Incoterms</dt><dd>{actualInput.incoterms||'To be confirmed'}</dd></div></dl><p className="quote-watermark">INTERNAL PREVIEW · 内部成本及毛利率仅供内部查看</p></div><div className="quote-email-preview"><div><h3>随附英文邮件</h3><button className="text-button" onClick={async()=>{try{await navigator.clipboard.writeText(`${selectedQuote.emailSubject}\n\n${selectedQuote.emailBody}`);setCopyNotice('已复制报价邮件。');}catch{setCopyNotice('请选中下方邮件文字手动复制。');}}}><Icon name="copy" size={14}/>复制</button></div><strong>{selectedQuote.emailSubject}</strong><pre>{selectedQuote.emailBody}</pre>{copyNotice&&<small role="status">{copyNotice}</small>}</div></>:<Empty title="先准备成本，再计算报价">明确填写各项成本与汇率。保存后，这里会显示确定金额与英文邮件草稿。</Empty>}</section>{selectedQuote&&<section className="panel approval-panel"><div className="panel-heading"><div><h2>审批与交付</h2><p>审批绑定 V{selectedQuote.version} 的报价及邮件内容。</p></div><Icon name="shield"/></div><div className="approval-content">{edited&&<div className="inline-note warning">当前表单有未保存内容；下方操作针对已保存的 V{selectedQuote.version}。</div>}{selectedQuote.rfqRevision!==detail.revision&&<div className="inline-note warning">询价已更新，请保存新的报价版本再提交审批。</div>}{selectedQuote.returnReason&&<div className="return-reason"><strong>主管退回原因</strong><p>{selectedQuote.returnReason}</p></div>}{detail.blockers>0&&<div className="approval-blocker"><span><Icon name="alert" size={15}/>{detail.blockers} 项阻塞需要先核实</span><button className="text-button" onClick={onReview}>返回审核<Icon name="arrow" size={13}/></button></div>}<div className="approval-actions">{sales&&['draft','returned'].includes(selectedQuote.status)&&<button className="button primary" disabled={!!busy||edited||selectedQuote.rfqRevision!==detail.revision} onClick={()=>act('submit',()=>post(`/api/quotes/${selectedQuote.id}/submit`),'报价已提交主管审批。')}><Icon name="shield" size={16}/>提交审批</button>}{!sales&&selectedQuote.status==='pending'&&<><button className="button primary" disabled={!!busy||detail.blockers>0||selectedQuote.rfqRevision!==detail.revision} onClick={()=>act('approve',()=>post(`/api/quotes/${selectedQuote.id}/approve`),'该版本已批准，可导出正式报价。')}><Icon name="check" size={16}/>批准此版本</button><div className="return-controls"><input aria-label="退回原因" placeholder="填写需修改的内容" value={reason} onChange={e=>setReason(e.target.value)}/><button className="button danger-outline" disabled={!!busy||!reason.trim()} onClick={()=>act('return',()=>post(`/api/quotes/${selectedQuote.id}/return`,{reason}),'报价已退回销售修改。')}>退回</button></div></>}<a className="button" href={`/api/quotes/${selectedQuote.id}/export?kind=internal`} target="_blank" rel="noreferrer"><Icon name="download" size={16}/>内部草稿导出</a>{selectedQuote.status==='approved'&&selectedQuote.rfqRevision===detail.revision?<a className="button" href={`/api/quotes/${selectedQuote.id}/export?kind=formal`} target="_blank" rel="noreferrer"><Icon name="download" size={16}/>正式报价导出</a>:<button className="button" disabled title="仅已批准且仍有效的报价可正式导出"><Icon name="download" size={16}/>批准后正式导出</button>}</div><p className="export-note">下载 HTML 后可用浏览器打印为 PDF。导出会留下操作记录。</p><div className="sent-confirm"><div><strong>{selectedQuote.sentAt?'已人工确认发送':'批准和导出之后，还差一次确认'}</strong><p>{selectedQuote.sentAt?`${date(selectedQuote.sentAt,true)} · 已建立报价后跟进任务`:'确认你已通过邮件客户端发送，再建立报价后的跟进任务。'}</p></div><button className="button small" disabled={!!busy||selectedQuote.status!=='approved'||!!selectedQuote.sentAt||selectedQuote.rfqRevision!==detail.revision} onClick={()=>act('sent',()=>post(`/api/quotes/${selectedQuote.id}/sent`),'已确认发送，并建立跟进任务；重复确认不会重复创建。')}><Icon name="check" size={15}/>{selectedQuote.sentAt?'已确认发送':'我已发送报价'}</button></div>{sales&&selectedQuote.status==='pending'&&<p className="role-hint">等待主管登录核实并批准，销售不能审批自己的报价。</p>}{!sales&&selectedQuote.status!=='pending'&&<p className="role-hint">销售负责准备和修改版本；主管审批已提交的报价。</p>}</div></section>}</div></div>;
}

function TaskBoard({tasks,users,rfqs,user,busy,act,onOpen,fixedRFQ}:{tasks:FollowUpTask[];users:User[];rfqs:RFQSummary[];user:User;busy:string;act:Act;onOpen:(id:string)=>void;fixedRFQ?:string}) {
 const [adding,setAdding]=useState(false);const [rfqId,setRFQ]=useState(fixedRFQ||rfqs[0]?.id||'');const [title,setTitle]=useState('');const [ownerId,setOwner]=useState(user.id);const [dueAt,setDue]=useState(dateInput(new Date(Date.now()+86400000)));const [postponing,setPostponing]=useState<string|null>(null);const [postponeDate,setPostponeDate]=useState('');
 const now=Date.now(); const overdue=tasks.filter(t=>t.status==='pending'&&new Date(t.dueAt).getTime()<now);const pending=tasks.filter(t=>t.status==='pending'&&new Date(t.dueAt).getTime()>=now);const done=tasks.filter(t=>t.status==='completed');
 async function add(e:FormEvent){e.preventDefault();const ok=await act('add-task',()=>post('/api/tasks',{rfqId:fixedRFQ||rfqId,title,ownerId,dueAt:new Date(dueAt).toISOString()}),'跟进任务已创建。');if(ok){setTitle('');setAdding(false);}}
 function card(task:FollowUpTask,isOverdue:boolean){return <article className={`task-card ${isOverdue?'overdue':''} ${task.status==='completed'?'completed':''}`} key={task.id}><div className="task-topline"><span className="task-customer">{task.customer}</span><button className="icon-button" aria-label={`打开 ${task.customer} 询价`} onClick={()=>onOpen(task.rfqId)}><Icon name="arrow" size={15}/></button></div><h3>{task.title}</h3><div className="task-due"><Icon name="clock" size={14}/>{date(task.dueAt,true)}{isOverdue&&<Tag tone="red">已逾期</Tag>}</div><div className="task-bottom"><span className="owner-cell"><i>{task.ownerName.slice(0,1)}</i>{task.ownerName}</span>{task.status==='pending'?<div><button className="text-button" onClick={()=>{setPostponing(task.id);setPostponeDate(dateInput(new Date(Math.max(Date.now(),new Date(task.dueAt).getTime())+86400000)));}}>延期</button><button className="complete-task" disabled={!!busy} onClick={()=>act(`complete-${task.id}`,()=>api(`/api/tasks/${task.id}`,{method:'PATCH',body:JSON.stringify({status:'completed'})}),'任务已完成，完成时间已记录。')}><Icon name="check" size={14}/>完成</button></div>:<span className="completed-date">完成于 {date(task.completedAt,true)}</span>}</div>{postponing===task.id&&<form className="postpone-form" onSubmit={e=>{e.preventDefault();void act('postpone',()=>api(`/api/tasks/${task.id}`,{method:'PATCH',body:JSON.stringify({dueAt:new Date(postponeDate).toISOString()})}),'任务到期时间已更新。').then(ok=>{if(ok)setPostponing(null);});}}><input aria-label="新的到期时间" type="datetime-local" value={postponeDate} onChange={e=>setPostponeDate(e.target.value)} required/><button className="button small" disabled={!!busy}>保存</button><button type="button" className="icon-button" aria-label="取消延期" onClick={()=>setPostponing(null)}><Icon name="close" size={15}/></button></form>}</article>;}
 return <section className="task-board"><div className="board-toolbar"><p><strong>{tasks.filter(t=>t.status==='pending').length}</strong> 项待办 <span className="dot-sep">·</span> 已批准和已导出的报价，需要人工确认发送后才自动创建跟进。</p><button className="button primary small" disabled={!rfqs.length} onClick={()=>{setRFQ(fixedRFQ||rfqs[0]?.id||'');setAdding(!adding);}}><Icon name="plus" size={16}/>新增跟进</button></div>{adding&&<form className="panel task-create-form" onSubmit={add}><label>关联询价<select value={fixedRFQ||rfqId} onChange={e=>setRFQ(e.target.value)} disabled={!!fixedRFQ} required>{rfqs.map(r=><option key={r.id} value={r.id}>{r.customer} · {r.id.slice(-6)}</option>)}</select></label><label className="task-title-input">任务内容<input value={title} onChange={e=>setTitle(e.target.value)} required placeholder="例如：确认客户是否收到报价"/></label><label>负责人<select value={ownerId} onChange={e=>setOwner(e.target.value)}>{users.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select></label><label>到期时间<input type="datetime-local" value={dueAt} onChange={e=>setDue(e.target.value)} required/></label><button className="button primary" disabled={!!busy}>创建任务</button><button className="icon-button" type="button" aria-label="取消新增任务" onClick={()=>setAdding(false)}><Icon name="close"/></button></form>}<div className="task-columns">{([{name:'需尽快跟进',tone:'red',items:overdue},{name:'计划中的跟进',tone:'green',items:pending},{name:'已完成',tone:'muted',items:done}] as const).map(column=><section className={`task-column ${column.tone}`} key={column.name}><div className="task-column-title"><span><i/>{column.name}</span><strong>{column.items.length}</strong></div>{column.items.length?column.items.sort((a,b)=>new Date(a.dueAt).getTime()-new Date(b.dueAt).getTime()).map(t=>card(t,column.tone==='red')):<div className="empty-column"><Icon name={column.tone==='muted'?'check':'clock'} size={24}/><p>{column.tone==='red'?'目前没有逾期任务':column.tone==='green'?'新的跟进会出现在这里':'完成的任务会保留在这里'}</p></div>}</section>)}</div></section>;
}
function auditLabel(action:string){const labels:Record<string,string>={'rfq.imported':'导入询价','field.edited':'更新字段','quote.created':'保存报价版本','quote.submitted':'提交报价审批','quote.approved':'批准报价','quote.returned':'退回报价','quote.formal_exported':'导出正式报价','quote.internal_exported':'导出内部草稿','quote.sent_confirmed':'确认报价已发送','task.created':'创建跟进任务','task.updated':'更新跟进任务','rfq.updated':'更新询价','review.time_recorded':'记录人工审核耗时','approval.invalidated':'审批已失效','rfq.processed':'询价解析完成','rfq.processing_failed':'询价解析失败','document.downloaded':'下载原始材料','quote.draft_saved':'暂存未完成报价'};return labels[action]||action;}

function auditDetail(action:string,detail:string):string {
 try {const d=JSON.parse(detail) as Record<string,unknown>;
 if(action==='field.edited')return `${FIELD_LABELS[String(d.key)]||d.key}：${String(d.before||'空')} → ${String(d.after||'空')} · ${d.confirmed?'已确认':'待核实'}`;
 if(d.version)return `报价 V${d.version}${d.total?` · ${d.currency} ${d.total}`:''}`;
 if(action==='quote.sent_confirmed')return '人工确认已发送，已关联报价后跟进任务。';
 if(d.seconds)return `本次人工操作 ${d.seconds} 秒（用户记录）`;
 if(d.reason)return String(d.reason);
 if(d.message)return String(d.message);
 if(action==='quote.draft_saved')return '暂存不完整的成本与条款，尚未形成可审批金额。';
 if(action==='rfq.imported')return `保留 ${d.files} 份原始材料${d.synthetic?' · 合成演示':''}`;
 if(action==='rfq.processed')return `${String(d.provider||'提取完成')} · ${d.documents} 份可读材料`;
 if(action==='task.updated')return [d.status==='completed'?'任务已完成':null,d.dueAt?`到期时间：${date(String(d.dueAt),true)}`:null,d.ownerId?'负责人已更新':null].filter(Boolean).join('；')||'任务信息已保存';
 if(action==='task.created')return '新增一项人工跟进任务。';
 if(action==='document.downloaded')return '已鉴权下载原始文件。';
 if(action==='rfq.updated')return [d.status?`状态：${RFQ_LABELS[d.status as RFQStatus]||d.status}`:null,d.ownerId?'负责人已更新':null].filter(Boolean).join('；');
 return '操作已保存，可关联当前询价和报价版本核对。';
 } catch {return detail;}
}
